var normalize = (s) => s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLocaleLowerCase("nl").replace(/[^a-z0-9]+/g, " ").trim();
var LETTERS = [...new Set(ENTRIES.map((e) => normalize(e.term)[0].toUpperCase()))];
var names = new Map(ENTRIES.map((e) => [e.id, normalize([e.term, ...e.aliases].join(" "))]));
var texts = new Map(ENTRIES.map((e) => [e.id, normalize([e.summary, ...e.explanation, ...e.steps, e.category].join(" "))]));
function findEntries(query, scope = "all") {
  const tokens = normalize(query).split(" ").filter(Boolean);
  const pool = ENTRIES.filter((e) => scope === "all" || e.scope === scope);
  const match = (s) => tokens.every((t) => s.includes(t));
  const direct = pool.filter((e) => match(names.get(e.id)));
  if (direct.length || !tokens.length) return { entries: direct, fullText: false };
  return { entries: pool.filter((e) => match(texts.get(e.id))), fullText: true };
}
function distance(a, b2) {
  let row = Array.from({ length: b2.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const next = [i];
    for (let j = 1; j <= b2.length; j++) next[j] = Math.min(next[j - 1] + 1, row[j] + 1, row[j - 1] + Number(a[i - 1] !== b2[j - 1]));
    row = next;
  }
  return row[b2.length];
}
function suggestions(query) {
  const q2 = normalize(query);
  if (q2.length < 4 || q2.length > 45) return [];
  return ENTRIES.map((e) => ({ entry: e, score: Math.min(...[e.term, ...e.aliases].map((n) => distance(q2, normalize(n)))) })).filter((x) => x.score <= Math.min(3, Math.floor(q2.length / 4))).sort((a, b2) => a.score - b2.score).slice(0, 3).map((x) => x.entry);
}

