  return { center: [(xmin + xmax) / 2, (ymin + ymax) / 2], scale: Math.min(Math.max(1, width - 100) / Math.max(0.1, xmax - xmin), Math.max(1, height - 100) / Math.max(0.1, ymax - ymin)) };
